using System;

class Program
{
    sealed class TreeNode
    {
        public TreeNode left;
        public TreeNode right;

        public static TreeNode Create(int depth)
        {
            if (depth > 0)
                return new TreeNode { left = Create(depth - 1), right = Create(depth - 1) };
            return new TreeNode();
        }

        public int Check()
        {
            return left == null ? 1 : 1 + left.Check() + right.Check();
        }
    }

    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        const int minDepth = 4;
        int maxDepth = n;
        int stretchDepth = maxDepth + 1;

        Console.WriteLine("stretch tree of depth {0}\t check: {1}",
            stretchDepth, TreeNode.Create(stretchDepth).Check());

        TreeNode longLived = TreeNode.Create(maxDepth);

        for (int depth = minDepth; depth <= maxDepth; depth += 2)
        {
            int iterations = 1 << (maxDepth - depth + minDepth);
            int check = 0;
            for (int i = 0; i < iterations; i++)
                check += TreeNode.Create(depth).Check();
            Console.WriteLine("{0}\t trees of depth {1}\t check: {2}",
                iterations, depth, check);
        }

        Console.WriteLine("long lived tree of depth {0}\t check: {1}",
            maxDepth, longLived.Check());
    }
}
