using System;
using System.IO;
using System.Text;

class Program
{
    const int IM = 139968;
    const int IA = 3877;
    const int IC = 29573;
    const int LineLen = 60;

    static int seed = 42;

    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        using var stream = new BufferedStream(Console.OpenStandardOutput(), 64 * 1024);

        const string alu =
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
            "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
            "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
            "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
            "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

        RepeatFasta(stream, ">ONE Homo sapiens alu\n", alu, 2 * n);

        byte[] iub = MakeLookup(
            new[] { 'a', 'c', 'g', 't', 'B', 'D', 'H', 'K', 'M', 'N', 'R', 'S', 'V', 'W', 'Y' },
            new[] { 0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02 });
        RandomFasta(stream, ">TWO IUB ambiguity codes\n", iub, 3 * n);

        byte[] hs = MakeLookup(
            new[] { 'a', 'c', 'g', 't' },
            new[] { 0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008 });
        RandomFasta(stream, ">THREE Homo sapiens frequency\n", hs, 5 * n);
    }

    static byte[] MakeLookup(char[] chars, double[] probs)
    {
        int n = chars.Length;
        var cum = new double[n];
        double cp = 0.0;
        for (int i = 0; i < n; i++)
        {
            cp += probs[i];
            cum[i] = cp;
        }

        var table = new byte[IM];
        int j = 0;
        for (int i = 0; i < IM; i++)
        {
            double r = (double)i / IM;
            while (j < n - 1 && r >= cum[j])
                j++;
            table[i] = (byte)chars[j];
        }
        return table;
    }

    static void RepeatFasta(Stream stream, string header, string alu, int n)
    {
        byte[] hdr = Encoding.ASCII.GetBytes(header);
        stream.Write(hdr, 0, hdr.Length);

        byte[] src = Encoding.ASCII.GetBytes(alu);
        int aluLen = src.Length;
        var ext = new byte[aluLen + LineLen];
        Buffer.BlockCopy(src, 0, ext, 0, aluLen);
        Buffer.BlockCopy(src, 0, ext, aluLen, LineLen);

        var line = new byte[LineLen + 1];
        line[LineLen] = (byte)'\n';

        int pos = 0;
        while (n >= LineLen)
        {
            Buffer.BlockCopy(ext, pos, line, 0, LineLen);
            stream.Write(line, 0, LineLen + 1);
            pos += LineLen;
            if (pos >= aluLen) pos -= aluLen;
            n -= LineLen;
        }
        if (n > 0)
        {
            Buffer.BlockCopy(ext, pos, line, 0, n);
            line[n] = (byte)'\n';
            stream.Write(line, 0, n + 1);
        }
    }

    static void RandomFasta(Stream stream, string header, byte[] lookup, int n)
    {
        byte[] hdr = Encoding.ASCII.GetBytes(header);
        stream.Write(hdr, 0, hdr.Length);

        var line = new byte[LineLen + 1];
        line[LineLen] = (byte)'\n';
        int s = seed;

        while (n >= LineLen)
        {
            for (int i = 0; i < LineLen; i++)
            {
                s = (s * IA + IC) % IM;
                line[i] = lookup[s];
            }
            stream.Write(line, 0, LineLen + 1);
            n -= LineLen;
        }
        if (n > 0)
        {
            for (int i = 0; i < n; i++)
            {
                s = (s * IA + IC) % IM;
                line[i] = lookup[s];
            }
            line[n] = (byte)'\n';
            stream.Write(line, 0, n + 1);
        }
        seed = s;
    }
}
