using System;
using System.Globalization;
using System.IO;
using System.Text;
using System.Threading.Tasks;

internal static class Program
{
    private static readonly CultureInfo Inv = CultureInfo.InvariantCulture;
    private const string NucMap = "ACTG";

    private static readonly byte[] EncodeLut = CreateEncodeLut();

    private static byte[] CreateEncodeLut()
    {
        var lut = new byte[256];
        for (int i = 0; i < lut.Length; i++) lut[i] = 255;
        lut[(byte)'A'] = lut[(byte)'a'] = 0;
        lut[(byte)'C'] = lut[(byte)'c'] = 1;
        lut[(byte)'T'] = lut[(byte)'t'] = 2;
        lut[(byte)'G'] = lut[(byte)'g'] = 3;
        return lut;
    }

    private static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        byte[] seq = ReadThreeSequence(n);

        string[] fragments =
        {
            "GGT",
            "GGTA",
            "GGTATT",
            "GGTATTTTAATT",
            "GGTATTTTAATTTATAGT"
        };

        Task<string> freq1 = Task.Run(() => FormatFrequencies(seq, 1));
        Task<string> freq2 = Task.Run(() => FormatFrequencies(seq, 2));
        var fragCounts = new Task<int>[fragments.Length];
        for (int i = 0; i < fragments.Length; i++)
        {
            int idx = i;
            fragCounts[idx] = Task.Run(() => CountFragment(seq, fragments[idx]));
        }

        var sb = new StringBuilder(2048);
        sb.Append(freq1.Result);
        sb.Append(freq2.Result);
        for (int i = 0; i < fragments.Length; i++)
        {
            sb.Append(fragCounts[i].Result.ToString(Inv));
            sb.Append('\t');
            sb.Append(fragments[i]);
            sb.Append('\n');
        }

        byte[] output = Encoding.ASCII.GetBytes(sb.ToString());
        Stream stdout = Console.OpenStandardOutput();
        stdout.Write(output, 0, output.Length);
    }

    private static byte[] ReadThreeSequence(int n)
    {
        using Stream stdin = Console.OpenStandardInput();
        using var ms = new MemoryStream(n > 0 ? n * 12 : 1 << 20);
        stdin.CopyTo(ms, 1 << 20);
        byte[] data = ms.GetBuffer();
        int dataLen = (int)ms.Length;

        int i = 0;
        while (i < dataLen)
        {
            if (data[i] == (byte)'>')
            {
                if (i + 5 < dataLen &&
                    data[i + 1] == (byte)'T' &&
                    data[i + 2] == (byte)'H' &&
                    data[i + 3] == (byte)'R' &&
                    data[i + 4] == (byte)'E' &&
                    data[i + 5] == (byte)'E')
                {
                    while (i < dataLen && data[i] != (byte)'\n') i++;
                    if (i < dataLen) i++;
                    break;
                }
            }
            i++;
        }

        int cap = n > 0 ? 5 * n : 4096;
        if (cap < 16) cap = 16;
        byte[] seq = new byte[cap];
        int j = 0;
        byte[] lut = EncodeLut;
        for (; i < dataLen; i++)
        {
            byte b = data[i];
            if (b == (byte)'>') break;
            byte e = lut[b];
            if (e != 255)
            {
                if (j == seq.Length)
                    Array.Resize(ref seq, seq.Length * 2);
                seq[j++] = e;
            }
        }
        Array.Resize(ref seq, j);
        return seq;
    }

    private static string FormatFrequencies(byte[] seq, int k)
    {
        int buckets = 1 << (2 * k);
        var counts = new long[buckets];
        int last = seq.Length - k + 1;
        if (last < 0) last = 0;

        if (k == 1)
        {
            for (int i = 0; i < seq.Length; i++)
                counts[seq[i]]++;
        }
        else
        {
            for (int i = 0; i < last; i++)
                counts[(seq[i] << 2) | seq[i + 1]]++;
        }

        var items = new (string mer, long count)[buckets];
        for (int key = 0; key < buckets; key++)
        {
            var chars = new char[k];
            int tmp = key;
            for (int p = k - 1; p >= 0; p--)
            {
                chars[p] = NucMap[tmp & 3];
                tmp >>= 2;
            }
            items[key] = (new string(chars), counts[key]);
        }

        Array.Sort(items, (a, b) =>
        {
            int cmp = b.count.CompareTo(a.count);
            return cmp != 0 ? cmp : string.CompareOrdinal(a.mer, b.mer);
        });

        double total = last;
        var sb = new StringBuilder(buckets * 16);
        for (int i = 0; i < items.Length; i++)
        {
            sb.Append(items[i].mer);
            sb.Append(' ');
            double pct = total > 0 ? 100.0 * items[i].count / total : 0.0;
            sb.Append(pct.ToString("F3", Inv));
            sb.Append('\n');
        }
        sb.Append('\n');
        return sb.ToString();
    }

    private static int CountFragment(byte[] seq, string fragment)
    {
        int k = fragment.Length;
        if (k <= 0 || seq.Length < k) return 0;

        ulong target = 0;
        for (int i = 0; i < k; i++)
            target = (target << 2) | (ulong)((fragment[i] >> 1) & 3);

        ulong mask = (k >= 32) ? ulong.MaxValue : ((1UL << (2 * k)) - 1);
        ulong rolling = 0;
        int count = 0;

        for (int i = 0; i < k - 1; i++)
            rolling = ((rolling << 2) | seq[i]) & mask;

        for (int i = k - 1; i < seq.Length; i++)
        {
            rolling = ((rolling << 2) | seq[i]) & mask;
            if (rolling == target) count++;
        }
        return count;
    }
}
