struct Body
{
    public double x, y, z, vx, vy, vz, mass;
}

sealed class NBodySystem
{
    const double PI = 3.141592653589793;
    const double SOLAR_MASS = 4.0 * PI * PI;
    const double DAYS_PER_YEAR = 365.24;

    Body b0, b1, b2, b3, b4;

    public NBodySystem()
    {
        b0.mass = SOLAR_MASS;

        b1.x = 4.84143144246472090e+00;
        b1.y = -1.16032004402742839e+00;
        b1.z = -1.03622044471123109e-01;
        b1.vx = 1.66007664274403694e-03 * DAYS_PER_YEAR;
        b1.vy = 7.69901118419740425e-03 * DAYS_PER_YEAR;
        b1.vz = -6.90460016972063023e-05 * DAYS_PER_YEAR;
        b1.mass = 9.54791938424326609e-04 * SOLAR_MASS;

        b2.x = 8.34336671824457987e+00;
        b2.y = 4.12479856412430479e+00;
        b2.z = -4.03523417114321381e-01;
        b2.vx = -2.76742510726862411e-03 * DAYS_PER_YEAR;
        b2.vy = 4.99852801234917238e-03 * DAYS_PER_YEAR;
        b2.vz = 2.30417297573763929e-05 * DAYS_PER_YEAR;
        b2.mass = 2.85885980666130812e-04 * SOLAR_MASS;

        b3.x = 1.28943695621391310e+01;
        b3.y = -1.51111514016986312e+01;
        b3.z = -2.23307578892655734e-01;
        b3.vx = 2.96440524057625081e-03 * DAYS_PER_YEAR;
        b3.vy = 2.37847173959480950e-03 * DAYS_PER_YEAR;
        b3.vz = -2.96589568540237556e-05 * DAYS_PER_YEAR;
        b3.mass = 4.36624404335156298e-05 * SOLAR_MASS;

        b4.x = 1.53796971148509165e+01;
        b4.y = -2.59193146099879641e+01;
        b4.z = 1.79258776959082653e-01;
        b4.vx = 2.68067772490389322e-03 * DAYS_PER_YEAR;
        b4.vy = 1.62824170038242295e-03 * DAYS_PER_YEAR;
        b4.vz = -9.51592254519715870e-05 * DAYS_PER_YEAR;
        b4.mass = 5.15138902046611451e-05 * SOLAR_MASS;

        double px = b1.vx * b1.mass + b2.vx * b2.mass + b3.vx * b3.mass + b4.vx * b4.mass;
        double py = b1.vy * b1.mass + b2.vy * b2.mass + b3.vy * b3.mass + b4.vy * b4.mass;
        double pz = b1.vz * b1.mass + b2.vz * b2.mass + b3.vz * b3.mass + b4.vz * b4.mass;
        b0.vx = -px / SOLAR_MASS;
        b0.vy = -py / SOLAR_MASS;
        b0.vz = -pz / SOLAR_MASS;
    }

    public void Advance(double dt, int n)
    {
        for (int i = 0; i < n; i++)
        {
            Pair(ref b0, ref b1, dt);
            Pair(ref b0, ref b2, dt);
            Pair(ref b0, ref b3, dt);
            Pair(ref b0, ref b4, dt);
            Pair(ref b1, ref b2, dt);
            Pair(ref b1, ref b3, dt);
            Pair(ref b1, ref b4, dt);
            Pair(ref b2, ref b3, dt);
            Pair(ref b2, ref b4, dt);
            Pair(ref b3, ref b4, dt);

            b0.x += dt * b0.vx; b0.y += dt * b0.vy; b0.z += dt * b0.vz;
            b1.x += dt * b1.vx; b1.y += dt * b1.vy; b1.z += dt * b1.vz;
            b2.x += dt * b2.vx; b2.y += dt * b2.vy; b2.z += dt * b2.vz;
            b3.x += dt * b3.vx; b3.y += dt * b3.vy; b3.z += dt * b3.vz;
            b4.x += dt * b4.vx; b4.y += dt * b4.vy; b4.z += dt * b4.vz;
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    static void Pair(ref Body a, ref Body b, double dt)
    {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        double dz = a.z - b.z;
        double d2 = dx * dx + dy * dy + dz * dz;
        double mag = dt / (d2 * Math.Sqrt(d2));
        double ma = a.mass * mag;
        double mb = b.mass * mag;
        a.vx -= dx * mb; a.vy -= dy * mb; a.vz -= dz * mb;
        b.vx += dx * ma; b.vy += dy * ma; b.vz += dz * ma;
    }

    public double Energy()
    {
        double e = 0.0;
        e += 0.5 * b0.mass * (b0.vx * b0.vx + b0.vy * b0.vy + b0.vz * b0.vz);
        e += 0.5 * b1.mass * (b1.vx * b1.vx + b1.vy * b1.vy + b1.vz * b1.vz);
        e += 0.5 * b2.mass * (b2.vx * b2.vx + b2.vy * b2.vy + b2.vz * b2.vz);
        e += 0.5 * b3.mass * (b3.vx * b3.vx + b3.vy * b3.vy + b3.vz * b3.vz);
        e += 0.5 * b4.mass * (b4.vx * b4.vx + b4.vy * b4.vy + b4.vz * b4.vz);
        e += Potential(ref b0, ref b1);
        e += Potential(ref b0, ref b2);
        e += Potential(ref b0, ref b3);
        e += Potential(ref b0, ref b4);
        e += Potential(ref b1, ref b2);
        e += Potential(ref b1, ref b3);
        e += Potential(ref b1, ref b4);
        e += Potential(ref b2, ref b3);
        e += Potential(ref b2, ref b4);
        e += Potential(ref b3, ref b4);
        return e;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    static double Potential(ref Body a, ref Body b)
    {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        double dz = a.z - b.z;
        return -(a.mass * b.mass) / Math.Sqrt(dx * dx + dy * dy + dz * dz);
    }
}
