    private static byte[] CreateComplement()
    {
        var map = new byte[256];
        for (int i = 0; i < 256; i++)
            map[i] = (byte)i;

        map['A'] = map['a'] = (byte)'T';
        map['B'] = map['b'] = (byte)'V';
        map['C'] = map['c'] = (byte)'G';
        map['D'] = map['d'] = (byte)'H';
        map['G'] = map['g'] = (byte)'C';
        map['H'] = map['h'] = (byte)'D';
        map['K'] = map['k'] = (byte)'M';
        map['M'] = map['m'] = (byte)'K';
        map['N'] = map['n'] = (byte)'N';
        map['R'] = map['r'] = (byte)'Y';
        map['S'] = map['s'] = (byte)'S';
        map['T'] = map['t'] = (byte)'A';
        map['U'] = map['u'] = (byte)'A';
        map['V'] = map['v'] = (byte)'B';
        map['W'] = map['w'] = (byte)'W';
        map['Y'] = map['y'] = (byte)'R';
        return map;
    }

    private static bool IsWhite(byte b) => b == (byte)'\n' || b == (byte)'\r' || b == (byte)' ' || b == (byte)'\t';

    private static void ReverseComplement(byte[] buf, int begin, int end)
    {
        int i = begin;
        int j = end - 1;
        var map = Comp;
        while (i <= j)
        {
            while (i <= j && IsWhite(buf[i])) i++;
            while (i <= j && IsWhite(buf[j])) j--;
            if (i <= j)
            {
                byte t = map[buf[i]];
                buf[i] = map[buf[j]];
                buf[j] = t;
                i++;
                j--;
            }
        }
    }

    private static void Main(string[] args)
    {
        _ = int.Parse(args[0]);

        byte[] buffer = new byte[1 << 20];
        int length = 0;
        using (var stdin = Console.OpenStandardInput())
        {
            while (true)
            {
                if (length == buffer.Length)
                    Array.Resize(ref buffer, buffer.Length * 2);
                int nread = stdin.Read(buffer, length, buffer.Length - length);
                if (nread == 0)
                    break;
                length += nread;
            }
        }

        int pos = 0;
        while (pos < length)
        {
            if (buffer[pos] != (byte)'>')
            {
                pos++;
                continue;
            }

            int headerEnd = pos;
            while (headerEnd < length && buffer[headerEnd] != (byte)'\n')
                headerEnd++;
            if (headerEnd < length)
                headerEnd++;

            int seqEnd = headerEnd;
            while (seqEnd < length && buffer[seqEnd] != (byte)'>')
                seqEnd++;

            ReverseComplement(buffer, headerEnd, seqEnd);
            pos = seqEnd;
        }

        using (var stdout = Console.OpenStandardOutput())
        {
            stdout.Write(buffer, 0, length);
            stdout.Flush();
        }
    }
