    static double EvalA(int i, int j)
    {
        return 1.0 / ((long)(i + j) * (i + j + 1) / 2 + i + 1);
    }

    static void MultAv(double[] v, double[] Av)
    {
        int n = v.Length;
        for (int i = 0; i < n; i++)
        {
            double sum = 0.0;
            for (int j = 0; j < n; j++)
                sum += EvalA(i, j) * v[j];
            Av[i] = sum;
        }
    }

    static void MultAtv(double[] v, double[] Atv)
    {
        int n = v.Length;
        for (int i = 0; i < n; i++)
        {
            double sum = 0.0;
            for (int j = 0; j < n; j++)
                sum += EvalA(j, i) * v[j];
            Atv[i] = sum;
        }
    }

